lse}]},{"id":"01a21eb5-b819-716e-b11a-9c5103501d5e","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"Which attack secretly intercepts and potentially alters communication between two parties?","difficulty":3,"approved":true,"explanation":"An attacker positioned between parties can observe or modify unprotected traffic.","alternatives":[{"id":"01a21eb5-b819-72ee-8c3c-1a917de39c6d","description":"Man-in-the-middle attack","correct_answer":true},{"id":"01a21eb5-b819-7a29-b378-72fce3606635","description":"Brute-force attack","correct_answer":false},{"id":"01a21eb5-b819-7589-b2a2-7bb636ec26fd","description":"Denial-of-service attack","correct_answer":false},{"id":"01a21eb5-b819-7b43-9bfd-14f2d7d56df3","description":"Dumpster diving","correct_answer":false}]},{"id":"01a21eb5-b819-7b57-a3ae-0541eb58a4b0","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"Which attack tries leaked username-password pairs on other services?","difficulty":3,"approved":true,"explanation":"Credential stuffing exploits people reusing passwords across sites.","alternatives":[{"id":"01a21eb5-b819-78d4-9400-a08e67c63ba8","description":"Credential stuffing","correct_answer":true},{"id":"01a21eb5-b819-7c49-b1bb-a889b2a68972","description":"Password spraying","correct_answer":false},{"id":"01a21eb5-b819-7d04-8c09-a7863d1acf54","description":"Rainbow table cracking","correct_answer":false},{"id":"01a21eb5-b819-77ab-98c4-137128c4fe8c","description":"Session fixation","correct_answer":false}]},{"id":"01a21eb5-b819-703f-9c06-9f5fc412efbf","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"Which attack tries a few commonly used login secrets against many accounts?","difficulty":3,"approved":true,"explanation":"Password spraying spreads attempts across accounts to reduce lockouts.","alternatives":[{"id":"01a21eb5-b819-7d24-b0cb-e16249bae61a","description":"Password spraying","correct_answer":true},{"id":"01a21eb5-b819-7dc3-bcde-1f6b35133f3c","description":"Credential stuffing","correct_answer":false},{"id":"01a21eb5-b819-70da-8ef1-514eb12e6d95","description":"Keystroke logging","correct_answer":false},{"id":"01a21eb5-b819-7251-86e7-df22c8ad2252","description":"ARP spoofing","correct_answer":false}]},{"id":"01a21eb5-b819-790e-addc-23df135ac140","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"What is random data added to each password before hashing called?","difficulty":3,"approved":true,"explanation":"Unique salts make precomputed attacks and identical-password matching harder.","alternatives":[{"id":"01a21eb5-b819-7e4e-83fc-b327bb31fdd5","description":"Salt","correct_answer":true},{"id":"01a21eb5-b819-7198-af09-972f33e601c4","description":"Session key","correct_answer":false},{"id":"01a21eb5-b819-7a6d-826e-148977258813","description":"Nonce","correct_answer":false},{"id":"01a21eb5-b819-7502-b5e5-5c33ed98f98f","description":"Checksum","correct_answer":false}]},{"id":"01a21eb5-b819-75b5-b1d5-c52c09037429","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"Which one-way operation maps data of any size to a fixed-size digest?","difficulty":3,"approved":true,"explanation":"A secure hash is designed to be difficult to reverse or forge through collisions.","alternatives":[{"id":"01a21eb5-b819-78fa-93c5-0ff5f3595748","description":"Cryptographic hashing","correct_answer":true},{"id":"01a21eb5-b819-72a3-9bce-bc1620bd8ec0","description":"Symmetric encryption","correct_answer":false},{"id":"01a21eb5-b819-7fda-a972-7a79e7d3f4f3","description":"Lossless compression","correct_answer":false},{"id":"01a21eb5-b819-7e01-b92e-eabadfc84ed8","description":"Digital watermarking","correct_answer":false}]},{"id":"01a21eb5-b819-71a9-a0cb-f82c5bc241fb","category":"01a21e5d-ee8b-768b-8713-3f779a056aaa","question":"Which cryptographic method uses the same secret key for encryption and decryption?","difficulty":3,"approved":true,"explanation":"Symmetric encryption is efficient but requires a shared secret.","alternatives":[{"id":"01a21e